export const getall_product_stock = async (cb) => {
    let bdyq2 = {...getStore(qryStore())?.all_prods};
    bdyq2.params = {
        businessId:  getStore("profileUser")?.businessId
    }
    bdyq2.subQuerys = {}
    bdyq2.subQuerys.stock = 1;

    const res = fetchEncryptStream(bdyq2);
    const td = await res;
    if (td) {

        let sum = {}
        
        let Nar= [];
        let summt = 0;
        td.map(prd=>{
            if(prd?.inventory?.qty){
                summt += parseFloatToDecimal(prd?.inventory?.amount,2)*1;
                if(!sum[prd.unit]){
                    sum[prd.unit] = prd?.inventory?.qty;
                }
                else{
                    sum[prd.unit] += prd?.inventory?.qty;
                }

                Nar.push({
                    productId: prd.productId,
                    name: prd.name,
                    unit: prd.unit,
                    qty: (prd.inventory.qty*1).toFixed(2),
                    amount: (prd.inventory.amount*1).toFixed(2),
                    cost: (prd.inventory.amount / prd.inventory.qty *1).toFixed(2),
                })
            }
        });
        if(isValidFunction(cb)){
            cb({list:  sortProducts(Nar,"name"), total:summt, units: sum  });
        };
    }
};



export const group_prod_stock = async (mp_subm, cb) => {
    let bdyq2 = {...getStore(qryStore())?.group_prod_stock};
    bdyq2.params = {
        businessId:  getStore("profileUser")?.businessId
    }
    const res = fetchEncryptStream(bdyq2);
    const td = await res;
    if (td) {

        let inventoryBack = aisleJSON(td.comps);
        let cmp_amount = 0;
        let inv_amount = 0;
        let missing_amount = 0;
        let success = [];
        let hasError = [];


        ObjectKeys(mp_subm).map(recg=>{
            let newObbj = {...mp_subm[recg]};
            let amount = (mp_subm[recg].type === "debit"? 1 : -1) * mp_subm[recg].amount;
            let compAmount = parseFloatToDecimal(amount,2)*1;
            cmp_amount += compAmount;
            
            
            if(td.comps[mp_subm[recg].comprobanteId]){
                newObbj["inventory"] = td.comps[mp_subm[recg].comprobanteId];

                let invAmount = 0;
                ObjectKeys(td.comps[mp_subm[recg].comprobanteId]).map(vvve=>{
                    invAmount  = parseFloatToDecimal(invAmount,2)*1 +   parseFloatToDecimal(td.comps[mp_subm[recg].comprobanteId][vvve],2)*1;
                })

                invAmount = invAmount<0?invAmount*-1:invAmount;




                invAmount =  parseFloatToDecimal(invAmount,2)*1;
                newObbj["inventoryAmount"] = invAmount ;

                inv_amount += invAmount;
                
                
                compAmount = compAmount<0?compAmount*-1:compAmount;

                if(compAmount-invAmount!==0){
                    let diff = compAmount-invAmount;
                    missing_amount += diff;
                    hasError.push(newObbj);
                }
                else{
                    success.push(newObbj);
                }
                delete inventoryBack[mp_subm[recg].comprobanteId];
            }else{
                missing_amount += amount;
                
                hasError.push(newObbj);
            }
        });

        let inventoryBackTotal = 0;
        ObjectKeys(inventoryBack).map(recg=>{
            let invAmount = 0;
            ObjectKeys(inventoryBack[recg]).map(vvve=>{
                invAmount  = parseFloatToDecimal(invAmount,2)*1 +   parseFloatToDecimal(inventoryBack[recg][vvve],2)*1;
            })
            inventoryBackTotal += invAmount

        })

       
        updStore("inv_comprobantes_compare", {hasError,success, inventoryBack });
        if(isValidFunction(cb)){
            cb();
        };
    }
};




