export function GroupbyInv(arr) {
    var obj = { };
    let arr1 = arr && ObjectKeys(arr)
    if (arr1.length > 0) {
      arr1.map((ele) => {
        let s = arr[ele];
        if(!obj[s.comprobanteId]){
            obj[s.comprobanteId] = {};
            obj[s.comprobanteId].amount= 0;
            obj[s.comprobanteId].document = s.document;
            obj[s.comprobanteId].date = s.date;
            obj[s.comprobanteId].comprobanteId = s.comprobanteId;
            obj[s.comprobanteId].entriesInvoiceId = s.entriesInvoiceId;
            obj[s.comprobanteId]["products"] = [];
        }
        obj[s.comprobanteId].amount += s.qty * s.price;
        obj[s.comprobanteId]["products"].push({
            productId: s.productId,
            qty: s.qty,
            price: s.price,
            inventoryId: s.inventoryId,
        });
      });
    } else {
      obj = null;
    }
    return obj;
  }







export function GroupbyAcc(arr, isPay) {
    let key =  "product";
    var obj = {
        "operations":[]
    };
    let balance = 0;

    let arr1 = arr && ObjectKeys(arr)
    if (arr1.length > 0) {
      arr1.map((ele) => {
        let s = arr[ele];
        if(s["type"]){
            if(isPay){
                balance += s["type"] === "debit" ? s["amount"] * -1 : s["amount"] * 1;
            }
            else{
                balance += s["type"] === "credit" ? s["amount"] * -1 : s["amount"] * 1;
            }
            obj["operations"].push(convert4acc(s));
        }
      });
    } else {
      obj = null;
    }
    return obj;
  }



  export function convert4acc(s) {
    let nItm = {};
    nItm["product"] =  getStore("products_ids")?.[s["product"]];
    nItm["sub_product"] = getStore("sub_products_ids")?.[s["subProduct"]];
    nItm["comprobanteId"] = s["comprobanteId"];
    nItm["document"] = s["document"];
    nItm["date"] = s["date"];
    if(s["type"]==="credit"){
        nItm["debit"] = 0;
        nItm["credit"] = s["amount"];
        
    }
    else if(s["type"]==="debit"){
        nItm["credit"] = 0;
        nItm["debit"] = s["amount"];
    }
    return nItm;
  }



  
//  sorting episodes comparing inputs to save in cache
export const sortProducts = (td, key, order = true) =>
callbackOnMemory(
	"sortProducts",
	[td],
	() => {
		let sortedA = td && td.sort((a, b) => {
			let A = a[key];
			let B = b[key];
			if (A < B) {
				return order ? -1 : 1;
			}
			if (A > B) {
				return order ? 1 : -1;
			}
			return 0;
        });
		return sortedA;
	}
);




